$b17herbs = [
    ['name' => 'Shi Jun Zi', 'latin' => 'Quisqualis Fructus', 'meta' => $b17text('Sweet, warm · Spleen, Stomach · 9–12 g', 'Dulce, tibia · Bazo, Estómago · 9–12 g'), 'focus' => $b17text('A gentle, child-friendly choice for roundworms and pinworms that also strengthens the Spleen and reduces childhood food accumulation.', 'Opción suave y apropiada para niños con ascárides u oxiuros; además fortalece el Bazo y reduce acumulación alimentaria infantil.'), 'clue' => $b17text('Parasites plus poor appetite, abdominal distention or childhood nutritional impairment.', 'Parásitos más poco apetito, distensión abdominal o deterioro nutricional infantil.'), 'safety' => $b17text('Do not take with hot tea. Raw fruit or overdose can cause hiccup, vomiting, diarrhea, neurologic symptoms and shock.', 'No tomar con té caliente. Fruto crudo o sobredosis puede causar hipo, vómito, diarrea, síntomas neurológicos y choque.'), 'preparation' => $b17text('Dry-frying improves flavor and safety; the prepared seed is traditionally chewed. Do not exceed age-based seed limits in children.', 'El tostado en seco mejora sabor y seguridad; la semilla preparada se mastica tradicionalmente. No exceder límites por edad en niños.'), 'official' => false],
    ['name' => 'Ku Lian Pi', 'latin' => 'Meliae Cortex', 'meta' => $b17text('Bitter, cold, toxic · Liver, Spleen, Stomach · 4.5–9 g', 'Amarga, fría, tóxica · Hígado, Bazo, Estómago · 4.5–9 g'), 'focus' => $b17text('A strong antiparasitic for roundworms, hookworms and pinworms; also used for vaginal Trichomonas and topically for tinea.', 'Antiparasitaria fuerte para ascárides, anquilostomas y oxiuros; también para Trichomonas vaginal y tópicamente para tiña.'), 'clue' => $b17text('Stronger parasite killing than Shi Jun Zi when constitution and digestion can tolerate bitter cold.', 'Mayor potencia antiparasitaria que Shi Jun Zi cuando la constitución y digestión toleran su frío amargo.'), 'safety' => $b17text('Toxic even within the usual range. Avoid long courses, pregnancy, weak constitution, peptic ulcer, anemia, and liver or heart disease.', 'Tóxica aun dentro del rango habitual. Evitar cursos largos, embarazo, constitución débil, úlcera, anemia y enfermedad hepática o cardíaca.'), 'preparation' => $b17text('Specify stem bark or root bark and verified Melia species.', 'Especificar corteza de tallo o raíz y especie Melia verificada.'), 'official' => false],
    ['name' => 'Fei Zi', 'latin' => 'Torreyae Semen', 'meta' => $b17text('Sweet, astringent, neutral · Large Intestine, Lung, Stomach · 15–30 g decocted; 9–15 g dry-fried', 'Dulce, astringente, neutra · Intestino Grueso, Pulmón, Estómago · 15–30 g en decocción; 9–15 g tostada'), 'focus' => $b17text('Kills many intestinal parasites without injuring the Spleen and Stomach; also moistens the Intestines and Lungs.', 'Elimina muchos parásitos intestinales sin lesionar Bazo y Estómago; también humedece Intestinos y Pulmón.'), 'clue' => $b17text('Hookworms or pinworms with dry cough or constipation; broader and more moistening than Shi Jun Zi.', 'Anquilostomas u oxiuros con tos seca o estreñimiento; más amplia y humectante que Shi Jun Zi.'), 'safety' => $b17text('Avoid in loose stools or hot-phlegm cough. Consider contraindicated during pregnancy; do not combine with mung beans.', 'Evitar con heces sueltas o tos por Flema-Calor. Considerar contraindicada en embarazo; no combinar con frijol mungo.'), 'preparation' => $b17text('Pulverize before use. Dry-frying with sand strengthens the Spleen and food-stagnation action.', 'Pulverizar antes de usar. Tostarla con arena fortalece su acción sobre Bazo y estancamiento alimentario.'), 'official' => false],
    ['name' => 'He Shi', 'latin' => 'Carpesii abrotanoidis Fructus', 'meta' => $b17text('Bitter, acrid, neutral, slightly toxic · Spleen, Stomach · 3–9 g', 'Amarga, acre, neutra, ligeramente tóxica · Bazo, Estómago · 3–9 g'), 'focus' => $b17text('Treats abdominal pain from roundworms, pinworms, hookworms or tapeworms; external combinations address vaginal itching.', 'Trata dolor abdominal por ascárides, oxiuros, anquilostomas o tenias; combinaciones externas tratan prurito vaginal.'), 'clue' => $b17text('Parasite accumulation where abdominal pain is the dominant symptom.', 'Acumulación parasitaria donde domina el dolor abdominal.'), 'safety' => $b17text('May cause tinnitus, nausea, diarrhea and abdominal pain; overdose may cause vomiting, weakness and clonic spasms. Pregnancy caution.', 'Puede causar tinnitus, náusea, diarrea y dolor abdominal; sobredosis puede causar vómito, debilidad y espasmos clónicos. Cautela en embarazo.'), 'preparation' => $b17text('Northern He Shi is Carpesium; verify identity because several regional species share the name.', 'He Shi del norte es Carpesium; verificar identidad porque varias especies regionales comparten el nombre.'), 'official' => false],
    ['name' => 'Nan He Shi', 'latin' => 'Carotae Fructus', 'meta' => $b17text('Bitter, acrid, neutral, slightly toxic · Spleen, Stomach · 3–9 g', 'Amarga, acre, neutra, ligeramente tóxica · Bazo, Estómago · 3–9 g'), 'focus' => $b17text('Wild-carrot seed used for roundworms, pinworms and tapeworms; externally combined for vaginitis.', 'Semilla de zanahoria silvestre usada para ascárides, oxiuros y tenias; se combina externamente para vaginitis.'), 'clue' => $b17text('The southern regional He Shi product; keep it distinct from Carpesii Fructus.', 'Producto regional sureño llamado He Shi; distinguirlo de Carpesii Fructus.'), 'safety' => $b17text('Do not use during pregnancy. High doses have caused headache, nausea, tinnitus and abdominal pain.', 'No usar durante el embarazo. Dosis altas han causado cefalea, náusea, tinnitus y dolor abdominal.'), 'preparation' => $b17text('Identity must state Daucus carota seed rather than relying on the shared market name He Shi.', 'La identidad debe indicar semilla de Daucus carota y no depender del nombre comercial compartido He Shi.'), 'official' => false],
    ['name' => 'Lei Wan', 'latin' => 'Omphalia', 'meta' => $b17text('Bitter, cold, slightly toxic · Large Intestine, Stomach · 6–15 g', 'Amarga, fría, ligeramente tóxica · Intestino Grueso, Estómago · 6–15 g'), 'focus' => $b17text('Especially important for tapeworms; also treats hookworms, roundworms, childhood accumulation and Damp-Heat skin patterns.', 'Especialmente importante para tenias; también trata anquilostomas, ascárides, acumulación infantil y patrones cutáneos de Calor-Humedad.'), 'clue' => $b17text('Tapeworm treatment requiring powder rather than a hot decoction.', 'Tratamiento de tenia que requiere polvo en vez de decocción caliente.'), 'safety' => $b17text('Use cautiously with Spleen or Stomach deficiency. Long-term use was traditionally warned to injure yin or fertility.', 'Usar con cautela en deficiencia de Bazo o Estómago. Tradicionalmente se advirtió que el uso prolongado lesiona yin o fertilidad.'), 'preparation' => $b17text('Do not decoct: its active enzymes are destroyed above 60°C. Grind the raw or low-temperature-dried herb and take with cool water.', 'No decoctar: sus enzimas activas se destruyen sobre 60 °C. Moler cruda o secada a baja temperatura y tomar con agua fresca.'), 'official' => false],
    ['name' => 'Wu Yi', 'latin' => 'Ulmi macrocarpae Fructus preparatus', 'meta' => $b17text('Bitter, acrid, warm · Spleen, Stomach · 3–9 g', 'Amarga, acre, tibia · Bazo, Estómago · 3–9 g'), 'focus' => $b17text('Expels roundworms and tapeworms and treats diarrhea-type childhood nutritional impairment; also used topically for tinea.', 'Expulsa ascárides y tenias y trata deterioro nutricional infantil tipo diarrea; también se usa tópicamente para tiña.'), 'clue' => $b17text('Parasites with cold-type food accumulation or chronic diarrhea.', 'Parásitos con acumulación alimentaria de tipo frío o diarrea crónica.'), 'safety' => $b17text('Contraindicated in Spleen or Stomach deficiency, dry-Heat, or when no parasite accumulation is present. Stop after effect.', 'Contraindicada en deficiencia de Bazo o Estómago, Calor-sequedad o sin acumulación parasitaria. Suspender tras lograr efecto.'), 'preparation' => $b17text('A fermented elm-fruit preparation with bark, red soil and chrysanthemum; verify the prepared product, not plain fruit.', 'Preparado fermentado de fruto de olmo con corteza, tierra roja y crisantemo; verificar el producto preparado, no el fruto simple.'), 'official' => false],
    ['name' => 'Bing Lang', 'latin' => 'Arecae Semen', 'meta' => $b17text('Acrid, bitter, warm · Large Intestine, Stomach · 6–15 g', 'Acre, amarga, tibia · Intestino Grueso, Estómago · 6–15 g'), 'focus' => $b17text('Broad antiparasitic—especially tapeworms—that drives qi downward, breaks accumulations, promotes urination and addresses food stagnation.', 'Antiparasitaria amplia—especialmente para tenias—que dirige Qi hacia abajo, rompe acumulaciones, promueve micción y trata estancamiento alimentario.'), 'clue' => $b17text('Parasites plus abdominal fullness, constipation, tenesmus, edema or marked qi/food stagnation.', 'Parásitos más plenitud abdominal, estreñimiento, tenesmo, edema o estancamiento marcado de Qi/alimentos.'), 'safety' => $b17text('Use cautiously with collapse or deficiency of middle qi. Over 30 g may cause salivation, vomiting, palpitations, convulsions and other toxicity.', 'Usar con cautela en colapso o deficiencia de Qi medio. Más de 30 g puede causar salivación, vómito, palpitaciones, convulsiones y otra toxicidad.'), 'preparation' => $b17text('Fresh is strongest; dry-fried is gentler for weak patients; scorched focuses on food stagnation. Date areca is not equivalent.', 'La fresca es más fuerte; tostada es más suave para débiles; chamuscada se enfoca en estancamiento alimentario. La areca inmadura no es equivalente.'), 'official' => true],
    ['name' => 'Mian Ma Guan Zhong', 'latin' => 'Dryopteridis crassirhizomae Rhizoma', 'meta' => $b17text('Bitter, cold · Liver, Stomach · 4.5–15 g', 'Amarga, fría · Hígado, Estómago · 4.5–15 g'), 'focus' => $b17text('Mildly expels tapeworms, roundworms and pinworms while clearing Heat-toxin; charred form cools Blood and stops bleeding.', 'Expulsa suavemente tenias, ascárides y oxiuros mientras aclara toxina-Calor; carbonizada enfría Sangre y detiene sangrado.'), 'clue' => $b17text('Parasites plus warm-toxin disease or bleeding signs.', 'Parásitos más enfermedad por toxina tibia o signos de sangrado.'), 'safety' => $b17text('Contraindicated in pregnancy and recent ulcer history. Never take with fatty/oily food; lipid absorption markedly increases severe filmarone toxicity.', 'Contraindicada en embarazo y antecedente reciente de úlcera. Nunca tomar con grasas/aceites; los lípidos aumentan mucho la toxicidad grave por filmarona.'), 'preparation' => $b17text('Unprepared form expels parasites and clears toxicity; charred form is specifically hemostatic. Exact species identification is difficult and essential.', 'La forma cruda expulsa parásitos y aclara toxicidad; carbonizada es específicamente hemostática. La identificación exacta de especie es difícil y esencial.'), 'official' => false],
    ['name' => 'Guan Zhong', 'latin' => 'Cyrtomii Rhizoma', 'meta' => $b17text('Bitter, astringent, cold · Liver, Lung, Large Intestine · 6–9 g', 'Amarga, astringente, fría · Hígado, Pulmón, Intestino Grueso · 6–9 g'), 'focus' => $b17text('Cyrtomium addendum that clears Heat-toxin, cools Blood, disperses stasis and expels intestinal parasites.', 'Adenda de Cyrtomium que aclara toxina-Calor, enfría Sangre, dispersa estasis y expulsa parásitos intestinales.'), 'clue' => $b17text('A regional Guan Zhong product with stronger Heat-toxin and Blood-level framing.', 'Producto regional Guan Zhong con énfasis mayor en toxina-Calor y nivel de Sangre.'), 'safety' => $b17text('Avoid pregnancy and overdose. Reported severe toxicity includes visual loss, convulsions, liver/kidney injury and cardiopulmonary failure.', 'Evitar embarazo y sobredosis. Toxicidad grave informada incluye pérdida visual, convulsiones, lesión hepatorrenal y falla cardiopulmonar.'), 'preparation' => $b17text('Do not substitute generically for Dryopteridis crassirhizomae; identify Cyrtomium fortunei explicitly.', 'No sustituir genéricamente por Dryopteridis crassirhizomae; identificar Cyrtomium fortunei explícitamente.'), 'official' => false],
    ['name' => 'Nan Gua Zi', 'latin' => 'Cucurbitae moschatae Semen', 'meta' => $b17text('Sweet, neutral · Large Intestine, Stomach · 30–60 g; 60–120 g for tapeworm', 'Dulce, neutra · Intestino Grueso, Estómago · 30–60 g; 60–120 g para tenia'), 'focus' => $b17text('A food-like, generally safe stand-alone herb for tapeworms and roundworms; also used in high doses for schistosomiasis.', 'Hierba alimenticia y generalmente segura usada sola para tenias y ascárides; también en dosis altas para esquistosomiasis.'), 'clue' => $b17text('Tapeworm when a gentle, high-dose seed can be eaten directly or decocted.', 'Tenia cuando puede usarse una semilla suave en dosis alta, consumida directamente o en decocción.'), 'safety' => $b17text('One anaphylactic-shock case has been reported. Excessive consumption may clog qi and the diaphragm.', 'Se informó un caso de choque anafiláctico. Consumo excesivo puede obstruir Qi y diafragma.'), 'preparation' => $b17text('Water-soluble active constituent permits decoction; kernels may also be eaten directly.', 'El componente activo soluble en agua permite decocción; las semillas también pueden comerse directamente.'), 'official' => false],
    ['name' => 'Da Suan', 'latin' => 'Allii sativi Bulbus', 'meta' => $b17text('Acrid, warm · Large Intestine, Lung, Spleen, Stomach · 4.5–9 g', 'Acre, tibia · Intestino Grueso, Pulmón, Bazo, Estómago · 4.5–9 g'), 'focus' => $b17text('Garlic kills hookworms and pinworms, resolves toxicity and abscesses, warms the middle and moves food or qi stagnation.', 'El ajo elimina anquilostomas y oxiuros, resuelve toxicidad y abscesos, calienta el centro y mueve estancamiento alimentario o de Qi.'), 'clue' => $b17text('Parasites with cold, food stagnation, tinea or toxic swelling; often adjunctive rather than sufficient alone.', 'Parásitos con frío, estancamiento alimentario, tiña o hinchazón tóxica; suele ser coadyuvante, no suficiente sola.'), 'safety' => $b17text('Avoid yin-deficiency Heat, mouth/throat lesions and prolonged skin application. Perianal or enema use is contraindicated during pregnancy.', 'Evitar Calor por deficiencia de yin, lesiones de boca/garganta y aplicación cutánea prolongada. Uso perianal o enema contraindicado en embarazo.'), 'preparation' => $b17text('Fresh crushed garlic is used internally or briefly topically; its strong acridity can irritate skin and mucosa.', 'Ajo fresco triturado se usa internamente o tópicamente por poco tiempo; su acritud fuerte puede irritar piel y mucosa.'), 'official' => false],
    ['name' => 'Chang Shan', 'latin' => 'Dichroae Radix', 'meta' => $b17text('Bitter, acrid, cold, toxic · Heart, Liver, Lung · 4.5–9 g', 'Amarga, acre, fría, tóxica · Corazón, Hígado, Pulmón · 4.5–9 g'), 'focus' => $b17text('Checks malarial disorders by transforming accumulated phlegm; it can also induce vomiting to expel congested phlegm.', 'Controla trastornos maláricos transformando Flema acumulada; también puede inducir vómito para expulsar Flema congestionada.'), 'clue' => $b17text('Malaria rooted in phlegm and Dampness; Chai Hu treats the lesser-yang branch while Chang Shan attacks the phlegm root.', 'Malaria arraigada en Flema y Humedad; Chai Hu trata la rama Shaoyang y Chang Shan ataca la raíz de Flema.'), 'safety' => $b17text('Contraindicated in pregnancy; use cautiously in debilitated patients. Toxic doses cause violent vomiting, bleeding, arrhythmia, hypotension and circulatory failure.', 'Contraindicada en embarazo; cautela en debilitados. Dosis tóxicas causan vómito violento, sangrado, arritmia, hipotensión y falla circulatoria.'), 'preparation' => $b17text('Bran- or wine-preparation reduces vomiting and gastrointestinal irritation. Shu Qi leaf is stronger and more emetic.', 'Preparación con salvado o vino reduce vómito e irritación gastrointestinal. La hoja Shu Qi es más fuerte y emética.'), 'official' => false],
];

