    [$b17text('Which broad antiparasitic also drives qi downward, resolves accumulation and promotes urination?', '¿Qué antiparasitaria amplia también dirige Qi hacia abajo, resuelve acumulación y promueve micción?'), '<strong>Bing Lang.</strong>'],
    [$b17text('Which fern product must never be taken with fatty or oily food?', '¿Qué producto de helecho nunca debe tomarse con comida grasa o aceitosa?'), '<strong>Mian Ma Guan Zhong.</strong>'],
    [$b17text('Which food-like seed is a gentle high-dose choice for tapeworm?', '¿Qué semilla alimenticia es una opción suave en dosis alta para tenia?'), '<strong>Nan Gua Zi.</strong>'],
